contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient) public payable {
        require(recipient != address(0));
        require(recipient != address(this));

        uint beforeRecipient = recipient.balance;
        uint beforeContract = address(c).balance;

        bool firstReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint midRecipient = recipient.balance;
        uint midContract = address(c).balance;

        bool secondReverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        bool firstSucceededNoEtherMoved = !firstReverted && midRecipient == beforeRecipient && midContract == beforeContract;
        bool firstSucceededExact100 = !firstReverted && midRecipient == beforeRecipient + 100 && midContract == beforeContract - 100;
        bool firstFailedNoEtherMoved = firstReverted && midRecipient == beforeRecipient && midContract == beforeContract;

        assert((firstSucceededExact100 || firstFailedNoEtherMoved) && (firstReverted || secondReverted) && recipient.balance == midRecipient && address(c).balance == midContract);
    }

    receive() external payable {}
}

